def sum_twin_primes_below(n):
    if n < 2:
        return 0
    limit = n + 2
    sieve = [True] * limit
    sieve[0] = sieve[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit, i):
                sieve[j] = False
    total = 0
    for p in range(2, n):
        if sieve[p] and ((p - 2 >= 0 and sieve[p - 2]) or sieve[p + 2]):
            total += p
    return total

