def meets_basic_password_policy(s):
    if len(s) < 8:
        return False
    upper = lower = digit = False
    for ch in s:
        if ch.isupper():
            upper = True
        elif ch.islower():
            lower = True
        elif ch.isdigit():
            digit = True
    return upper and lower and digit

def pad_hex(n, width):
    digits = "0123456789ABCDEF"
    hex_chars = []
    x = n
    if x == 0:
        hex_chars.append('0')
    while x > 0:
        hex_chars.append(digits[x % 16])
        x //= 16
    hex_str = ''.join(reversed(hex_chars))
    if len(hex_str) < width:
        hex_str = '0' * (width - len(hex_str)) + hex_str
    return hex_str

def is_valid_simple_html_tags(s):
    stack = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] != '<':
            return False
        closing = s[i:i+2] == '</'
        start = i + 2 if closing else i + 1
        if start >= n or not s[start].isalpha() or not s[start].islower():
            return False
        letter = s[start]
        end = start + 1
        if end >= n or s[end] != '>':
            return False
        if closing:
            if not stack or stack.pop() != letter:
                return False
        else:
            stack.append(letter)
        i = end + 1
    return not stack

