def mask_phone_middle(digits):
    n = len(digits)
    if n <= 5:
        return '*' * n
    chars = []
    for i, ch in enumerate(digits):
        if i < 3 or i >= n - 2:
            chars.append(ch)
        else:
            chars.append('*')
    return ''.join(chars)

